20	package patch
21	
22	import (
23		"encoding/json"
24		"fmt"
25		"strings"
26	)
27	
28	type PatchOperation struct {
29		Op    string      `json:"op"`
30		Path  string      `json:"path"`
31		Value interface{} `json:"value"`
32	}
33	
34	const (
35		PatchReplaceOp = "replace"
36		PatchTestOp    = "test"
37		PatchAddOp     = "add"
38		PatchRemoveOp  = "remove"
39	)
40	
41	func (p *PatchOperation) MarshalJSON() ([]byte, error) {
42		switch p.Op {
43		// The 'remove' operation is the only patching operation without a value
44		// and it needs to be parsed differently.
45		case PatchRemoveOp:
46			return json.Marshal(&struct {
47				Op   string `json:"op"`
48				Path string `json:"path"`
49			}{
50				Op:   p.Op,
51				Path: p.Path,
52			})
53		case PatchTestOp, PatchReplaceOp, PatchAddOp:
54			return json.Marshal(&struct {
55				Op    string      `json:"op"`
56				Path  string      `json:"path"`
57				Value interface{} `json:"value"`
58			}{
59				Op:    p.Op,
60				Path:  p.Path,
61				Value: p.Value,
62			})
63		default:
64			return nil, fmt.Errorf("operation %s not recognized", p.Op)
65		}
66	}
67	
68	type PatchSet struct {
69		patches []PatchOperation
70	}
71	
72	type PatchOption func(patches *PatchSet)
73	
74	func New(opts ...PatchOption) *PatchSet {
75		p := &PatchSet{}
76		p.AddOption(opts...)
77		return p
78	}
79	
80	func (p *PatchSet) GetPatches() []PatchOperation {
81		return p.patches
82	}
83	
84	func (p *PatchSet) AddOption(opts ...PatchOption) {
85		for _, f := range opts {
86			f(p)
87		}
88	}
89	
90	func (p *PatchSet) addOp(op, path string, value interface{}) {
91		p.patches = append(p.patches, PatchOperation{
92			Op:    op,
93			Path:  path,
94			Value: value,
95		})
96	}
97	
98	func WithTest(path string, value interface{}) PatchOption {
99		return func(p *PatchSet) {
100			p.addOp(PatchTestOp, path, value)
101		}
102	}
103	
104	func WithAdd(path string, value interface{}) PatchOption {
105		return func(p *PatchSet) {
106			p.addOp(PatchAddOp, path, value)
107		}
108	}
109	
110	func WithReplace(path string, value interface{}) PatchOption {
111		return func(p *PatchSet) {
112			p.addOp(PatchReplaceOp, path, value)
113		}
114	}
115	
116	func WithRemove(path string) PatchOption {
117		return func(p *PatchSet) {
118			p.addOp(PatchRemoveOp, path, nil)
119		}
120	}
121	
122	func (p *PatchSet) GeneratePayload() ([]byte, error) {
123		return GeneratePatchPayload(p.patches...)
124	}
125	
126	func (p *PatchSet) IsEmpty() bool {
127		return len(p.patches) < 1
128	}
129	
130	func (p *PatchSet) ToSlice() ([]string, error) {
131		var result []string
132	
133		for _, operation := range p.patches {
134			patch, err := operation.MarshalJSON()
135			if err != nil {
136				return nil, err
137			}
138	
139			result = append(result, string(patch))
140		}
141	
142		return result, nil
143	}
144	
145	func GeneratePatchPayload(patches ...PatchOperation) ([]byte, error) {
146		if len(patches) == 0 {
147			return nil, fmt.Errorf("list of patches is empty")
148		}
149	
150		payloadBytes, err := json.Marshal(patches)
151		if err != nil {
152			return nil, err
153		}
154	
155		return payloadBytes, nil
156	}
157	
158	func GenerateTestReplacePatch(path string, oldValue, newValue interface{}) ([]byte, error) {
159		return GeneratePatchPayload(
160			PatchOperation{
161				Op:    PatchTestOp,
162				Path:  path,
163				Value: oldValue,
164			},
165			PatchOperation{
166				Op:    PatchReplaceOp,
167				Path:  path,
168				Value: newValue,
169			},
170		)
171	}
172	
173	func UnmarshalPatch(patch []byte) ([]PatchOperation, error) {
174		var p []PatchOperation
175		err := json.Unmarshal(patch, &p)
176	
177		return p, err
178	}
179	
180	func EscapeJSONPointer(ptr string) string {
181		s := strings.ReplaceAll(ptr, "~", "~0")
182		return strings.ReplaceAll(s, "/", "~1")
183	}
