// objects and appends the JSON patch operations required to bring origMS in line
// with newMS to the provided patchSet.
//
// For each field that changed from its zero value to a non-zero value, an "add"
// operation is emitted at /status/migrationState/<jsonFieldName>. For fields that
// are non-zero in both objects but differ, a "test" followed by a "replace"
// operation is emitted. Unchanged fields produce no operations.
//
// When newMS is nil, a "test" followed by a "remove" operation is emitted at
// /status/migrationState, operating on the whole migration state object.
func addMigrationStateFieldPatches(patchSet *patch.PatchSet, origMS *virtv1.VirtualMachineInstanceMigrationState, newMS *virtv1.VirtualMachineInstanceMigrationState) {
	const basePath = "/status/migrationState"

	if newMS == nil {
		if origMS == nil {
			return
		}
		patchSet.AddOption(
			patch.WithTest(basePath, origMS),
			patch.WithRemove(basePath),
		)
		return
	}

	if origMS == nil {
		patchSet.AddOption(patch.WithAdd(basePath, newMS))
		return
	}

	origVal := reflect.ValueOf(*origMS)
	newVal := reflect.ValueOf(*newMS)
	t := origVal.Type()

	for i := 0; i < t.NumField(); i++ {
		field := t.Field(i)
		jsonTag := field.Tag.Get("json")
		if jsonTag == "" || jsonTag == "-" {
			continue
		}
		name := strings.SplitN(jsonTag, ",", 2)[0]
		if name == "" {
			continue
		}

		origField := origVal.Field(i)
		newField := newVal.Field(i)

		if reflect.DeepEqual(origField.Interface(), newField.Interface()) {
			// Field is unchanged, nothing to patch.
			continue
		}

		fieldPath := basePath + "/" + name
		if origField.IsZero() {
			// Field went from zero value to non-zero value.
			patchSet.AddOption(patch.WithAdd(fieldPath, newField.Interface()))
		} else if !newField.IsZero() {
			// Field is non-zero in both objects but the values differ.
			patchSet.AddOption(
				patch.WithTest(fieldPath, origField.Interface()),
				patch.WithReplace(fieldPath, newField.Interface()),
			)
		}
	}
}

